    void ExportBackup(){var d=new SaveFileDialog{FileName=$"MuWorld-backup-{DateTime.Now:yyyyMMdd}.json",Filter="MuWorld 백업|*.json"};if(d.ShowDialog(this)==true){store.ExportBackup(d.FileName);Notify("백업을 저장했습니다.");}}
    void ImportBackup(){var d=new OpenFileDialog{Filter="MuWorld 백업|*.json"};if(d.ShowDialog(this)==true){try{store.ImportBackup(d.FileName);Navigate("settings");Notify("백업을 검증하고 가져왔습니다.");}catch(Exception e){Notify("백업을 가져오지 못했습니다. "+e.Message);}}}
